from pathlib import Path
p=Path('public/images');p.mkdir(parents=True,exist_ok=True)
for name,color in [('hero','#d8d9db'),('sedan','#cacdd0'),('suv','#343b42'),('compact','#ba292d'),('offer','#e1e2e3')]:
 roof='M270 290 L340 180 Q360 158 420 158 L620 165 L715 284' if name=='suv' else 'M270 290 L370 205 Q395 190 450 192 L590 202 L700 284'
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="600" viewBox="0 0 1000 600"><defs><linearGradient id="paint" x2="0.3" y2="1"><stop stop-color="#fff"/><stop offset=".35" stop-color="{color}"/><stop offset="1" stop-color="#60656b"/></linearGradient><radialGradient id="wheel"><stop stop-color="#a9adb0"/><stop offset=".55" stop-color="#555d65"/><stop offset=".6" stop-color="#17191d"/><stop offset="1" stop-color="#080a0d"/></radialGradient></defs><ellipse cx="500" cy="437" rx="420" ry="28" fill="#000" opacity=".12"/><path d="{roof} L830 305 Q885 320 894 370 L875 408 L136 408 Q100 401 115 349 L160 311Z" fill="url(#paint)" stroke="#6f7479" stroke-width="3"/><path d="M302 283 L382 214 Q403 201 447 205 L577 214 L665 283Z" fill="#18242d"/><path d="M480 206 L480 284" stroke="#969ea6" stroke-width="8"/><path d="M137 340 L870 340" stroke="#fff" opacity=".6" stroke-width="3"/><path d="M693 299 L843 319 L824 335 L711 324Z" fill="#fafafa"/><path d="M126 326 L181 321 L180 344 L122 350Z" fill="#b5101d"/><path d="M723 357 L882 354 L871 385 L731 383Z" fill="#151b20"/><path d="M502 304 L545 304" stroke="#30383f" stroke-width="7" stroke-linecap="round"/><circle cx="277" cy="394" r="66" fill="url(#wheel)"/><circle cx="727" cy="394" r="66" fill="url(#wheel)"/><circle cx="277" cy="394" r="20" fill="#c2c7cc"/><circle cx="727" cy="394" r="20" fill="#c2c7cc"/></svg>'''
 (p/f'{name}.svg').write_text(svg)
(p/'logo.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="60" height="60" viewBox="0 0 60 60"><path fill="#e31b21" d="M9 12h42v9H20v18h22v-6H30v-9h21v24H9z"/><path fill="#ff7a7d" d="M9 12h42l-9 9H20z"/></svg>')
(p/'app.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="400" height="480" viewBox="0 0 400 480"><rect x="82" y="12" width="236" height="450" rx="34" fill="#17191b"/><rect x="92" y="24" width="216" height="425" rx="26" fill="#f5f3ee"/><rect x="158" y="32" width="84" height="18" rx="9" fill="#17191b"/><text x="112" y="99" font-family="Arial" font-size="17" font-weight="bold">GAWISH MOTORS</text><text x="112" y="144" font-family="Arial" font-size="25" font-weight="bold">Find your</text><text x="112" y="174" font-family="Arial" font-size="25" font-weight="bold">next chapter.</text><rect x="110" y="202" width="180" height="123" rx="8" fill="#e4e1da"/><path d="M125 274l18-26 31-17h57l27 22 17 11v26H125z" fill="#a32429"/><circle cx="153" cy="286" r="14" fill="#17191b"/><circle cx="251" cy="286" r="14" fill="#17191b"/><rect x="110" y="350" width="180" height="47" rx="4" fill="#a30f15"/><text x="135" y="380" fill="#fff" font-size="15" font-family="Arial">Explore models →</text></svg>')
